using System;using System.IO;using System.Linq;using System.Text;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class FinalFountainExistingWater{
const string ScenePath="Assets/Editor/DayNightBackups/Gangstar Final Env.unity",Dir="Assets/Scenes/Oasis/FinalEnvironmentRoads/GardenUtilityAtlas";
static FinalFountainExistingWater(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("FinalFountainExistingWater.request")||EditorApplication.isCompiling)return;File.Delete("FinalFountainExistingWater.request");Run();}
static void Photo(Scene s,Vector3 p,Vector3 target,string n)=>typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{s,p,target,n});
static void UpdatePrefab(string path,Material atlas,Material water){var p=PrefabUtility.LoadPrefabContents(path);try{foreach(var r in p.GetComponentsInChildren<MeshRenderer>(true).Where(r=>r.name.StartsWith("Fountain_")))r.sharedMaterials=new[]{atlas,water};PrefabUtility.SaveAsPrefabAsset(p,path,out bool okay);if(!okay)throw new Exception("Prefab save failed");}finally{PrefabUtility.UnloadPrefabContents(p);}}
static void Run(){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath(ScenePath);var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).ToArray();var native=all.FirstOrDefault(r=>r.name=="Water");var water=native?native.sharedMaterial:AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/Art/Environment/Materials/OasisWater_Mat.mat");if(!water)throw new Exception("Water material missing");var atlas=AssetDatabase.LoadAssetAtPath<Material>(Dir+"/City Garden Utility Atlas.mat");string backup="FinalEnvironmentRoadBackup/ExistingWater-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");Directory.CreateDirectory(backup);EditorSceneManager.SaveScene(scene,backup+"/Before.unity",true);var paths=new[]{"Assets/Scenes/Oasis/FinalEnvironmentRoads/Final Roads.prefab",Dir+"/City Atlas Gardens and Utilities.prefab"};for(int i=0;i<paths.Length;i++)File.Copy(paths[i],backup+"/Before-"+i+".prefab");
var fountains=all.Where(r=>r.name.StartsWith("Fountain_")).ToArray();foreach(var r in fountains){var mesh=r.GetComponent<MeshFilter>().sharedMesh;File.Copy(AssetDatabase.GetAssetPath(mesh),backup+"/"+mesh.name+".asset");var ids=mesh.triangles;var info=mesh.uv2;var solid=new List<int>();var fluid=new List<int>();for(int i=0;i<ids.Length;i+=3){var list=Mathf.RoundToInt(info[ids[i]].x)==13?fluid:solid;list.Add(ids[i]);list.Add(ids[i+1]);list.Add(ids[i+2]);}mesh.subMeshCount=2;mesh.SetTriangles(solid,0);mesh.SetTriangles(fluid,1);if(mesh.tangents.Length!=mesh.vertexCount)mesh.RecalculateTangents();EditorUtility.SetDirty(mesh);r.sharedMaterials=new[]{atlas,water};PrefabUtility.RecordPrefabInstancePropertyModifications(r);log.AppendLine(r.name+": basin and two bowls="+fluid.Count/3+" water triangles; original streams/spray retained");}
AssetDatabase.SaveAssets();foreach(var path in paths)UpdatePrefab(path,atlas,water);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);foreach(var r in fountains){var p=r.bounds.center;Photo(scene,p+new Vector3(8,5,-10),p,"Existing-Water-"+r.name);}int errors=ShaderUtil.GetShaderMessages(water.shader).Count(m=>m.severity.ToString()=="Error");if(errors>0)throw new Exception("Water shader errors="+errors);log.AppendLine("SUCCESS existing material="+AssetDatabase.GetAssetPath(water)+" shader="+water.shader.name+"; two fountains, scene and prefabs saved; no new material/texture/renderer; one additional water submesh draw per fountain; shader errors=0; backup="+backup);
}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/ExistingFountainWaterReport.txt",log.ToString());}}
